      expect((await res2.json()).id).toBe("idleh-2");
    } finally {
      vi.useRealTimers();
    }
  });

  it("idleTimeout expiration does not depend on the seal ttl", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
